drop table if exists public.posts cascade;
create table if not exists public.profiles (id text primary key, name text not null, emoji text not null default '', color text not null default '#ff8200', bio text not null default '', verified boolean not null default false, followers int not null default 0, following int not null default 0, created_at timestamptz not null default now());
create table if not exists public.posts (id text primary key default gen_random_uuid()::text, author_id text not null, content text not null, images text[] not null default '{}', created_at timestamptz not null default now(), repost_of_id text references public.posts(id) on delete set null, repost_comment text not null default '', reposts int not null default 0, topic text, source text not null default 'web', likes int not null default 0);
create table if not exists public.post_comments (id text primary key default gen_random_uuid()::text, post_id text not null references public.posts(id) on delete cascade, author_id text not null, content text not null, created_at timestamptz not null default now(), likes int not null default 0);
create table if not exists public.articles (id text primary key default gen_random_uuid()::text, author_id text not null, title text not null, summary text not null default '', content text not null, tags text[] not null default '{}', created_at timestamptz not null default now(), views int not null default 0, likes int not null default 0);
create table if not exists public.article_comments (id text primary key default gen_random_uuid()::text, article_id text not null references public.articles(id) on delete cascade, author_id text not null, content text not null, created_at timestamptz not null default now());
create table if not exists public.snippets (id text primary key default gen_random_uuid()::text, author_id text not null, title text not null, language text not null default 'text', code text not null, created_at timestamptz not null default now(), likes int not null default 0);
create table if not exists public.post_likes (user_id text not null, post_id text not null references public.posts(id) on delete cascade, created_at timestamptz not null default now(), primary key (user_id, post_id));
create table if not exists public.comment_likes (user_id text not null, comment_id text not null references public.post_comments(id) on delete cascade, created_at timestamptz not null default now(), primary key (user_id, comment_id));
create table if not exists public.article_likes (user_id text not null, article_id text not null references public.articles(id) on delete cascade, created_at timestamptz not null default now(), primary key (user_id, article_id));
create table if not exists public.snippet_likes (user_id text not null, snippet_id text not null references public.snippets(id) on delete cascade, created_at timestamptz not null default now(), primary key (user_id, snippet_id));
create table if not exists public.resources (id text primary key default gen_random_uuid()::text, title text not null, description text not null default '', category text not null default 'general', uploader text not null default 'official', size text not null default '0KB', downloads int not null default 0, type text not null default 'doc' check (type in ('pdf','video','code','doc')));
create table if not exists public.topics (id text primary key default gen_random_uuid()::text, name text not null unique, heat int not null default 0, "desc" text not null default '');
create table if not exists public.hot_searches (id text primary key default gen_random_uuid()::text, rank int not null, text text not null, heat int not null default 0, tag text check (tag in ('hot','new','boom','boil')));
create table if not exists public.notifications (id text primary key default gen_random_uuid()::text, user_id text not null, type text not null, from_user_id text not null, content text not null default '', post_id text, created_at timestamptz not null default now(), read boolean not null default false);
create table if not exists public.messages (id text not null, owner_id text not null, peer_id text not null, from_me boolean not null, content text not null, created_at timestamptz not null default now(), read boolean not null default false, primary key (id, owner_id));
create table if not exists public.favorites (id text primary key default gen_random_uuid()::text, user_id text not null, type text not null, target_id text not null, created_at timestamptz not null default now(), unique (user_id, type, target_id));
create table if not exists public.follows (follower_id text not null, followee_id text not null, created_at timestamptz not null default now(), primary key (follower_id, followee_id), check (follower_id <> followee_id));
create table if not exists public.post_drafts (id text primary key default gen_random_uuid()::text, user_id text not null, content text not null default '', topic text, images text[] not null default '{}', saved_at timestamptz not null default now());
create table if not exists public.article_drafts (id text primary key default gen_random_uuid()::text, user_id text not null, title text not null default '', content text not null default '', tags text[] not null default '{}', saved_at timestamptz not null default now());
create table if not exists public.documents (user_id text not null, key text not null, data jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now(), primary key (user_id, key));
create table if not exists public.roles (id text primary key default gen_random_uuid()::text, name text not null unique, description text not null default '', created_at timestamptz not null default now());
create table if not exists public.permissions (id text primary key default gen_random_uuid()::text, key text not null unique);
create table if not exists public.role_permissions (role_id text not null references public.roles(id) on delete cascade, permission_id text not null references public.permissions(id) on delete cascade, primary key (role_id, permission_id));
create table if not exists public.user_roles (user_id text not null, role_id text not null references public.roles(id) on delete cascade, created_at timestamptz not null default now(), primary key (user_id, role_id));
create table if not exists public.audit_logs (id bigint generated always as identity primary key, actor_id text, action text not null, target_type text not null default '', target_id text not null default '', detail jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index if not exists idx_posts_author_created on public.posts (author_id, created_at desc);
create index if not exists idx_posts_created on public.posts (created_at desc);
create index if not exists idx_post_comments_post on public.post_comments (post_id, created_at);
create index if not exists idx_articles_created on public.articles (created_at desc);
create index if not exists idx_article_comments_article on public.article_comments (article_id, created_at);
create index if not exists idx_notifications_user on public.notifications (user_id, created_at desc);
create index if not exists idx_messages_owner_peer on public.messages (owner_id, peer_id, created_at);
create index if not exists idx_favorites_user on public.favorites (user_id);
create index if not exists idx_follows_followee on public.follows (followee_id);
create index if not exists idx_user_roles_user on public.user_roles (user_id);
grant usage on schema public to anon, authenticated;
grant select on public.profiles, public.posts, public.post_comments, public.articles, public.article_comments, public.snippets, public.resources, public.topics, public.hot_searches to anon;
grant select, insert, update, delete on public.profiles, public.posts, public.post_comments, public.post_likes, public.comment_likes, public.article_likes, public.snippet_likes, public.articles, public.article_comments, public.snippets, public.notifications, public.messages, public.favorites, public.follows, public.post_drafts, public.article_drafts, public.documents to authenticated;
grant select on public.roles, public.permissions, public.role_permissions, public.user_roles, public.audit_logs to authenticated;
grant usage, select on all sequences in schema public to authenticated;
